{
  "file_name": "EquilateralTriangle",
  "hlsl_code": "// A filled equilateral triangle pointing upwards and centered on the screen.
// PLAN:
// 1) Define SDF helper for equilateral triangle.
// 2) In main function, center UV coordinates (p = UV - Center).
// 3) Scale space by 2.0 to normalize range, then pass Size to SDF.
// 4) Calculate signed distance.
// 5) Apply anti-aliasing using smoothstep and fwidth.
// 6) Output final color with alpha.

#ifndef PI
#define PI 3.14159265359
#endif

// SDF for an upright equilateral triangle centered at origin
// p: coordinate, r: circumradius (distance from center to vertex)
float sdEquilateralTriangle(float2 p, float r) {
    const float k = 1.7320508; // sqrt(3)
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0)
        p = float2(p.x - k * p.y, -k * p.x - p.y) * 0.5;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return -length(p) * sign(p.y);
}

void EquilateralTriangle_float(float2 UV, float2 Center, float Size, float4 Color, out float4 outColor) {
    // 1) Center and coordinate transformation
    // Map UV (0..1) to centered space relative to 'Center'
    // Multiply by 2.0 so that a Size of 1.0 roughly fills the -1..1 range
    float2 p = (UV - Center) * 2.0;

    // 2) Calculate Signed Distance Field
    // Size acts as the radius from center to vertex
    float dist = sdEquilateralTriangle(p, Size);

    // 3) Anti-aliasing
    // Use fwidth for pixel-perfect AA, with a minimum fallback for safety
    float aa = max(fwidth(dist), 0.001);

    // 4) Create Mask
    // dist is negative inside, positive outside. 
    // smoothstep from -aa to +aa creates a smooth transition at 0.
    // We want 1.0 inside (negative dist) and 0.0 outside.
    float mask = 1.0 - smoothstep(-aa, aa, dist);

    // 5) Output
    // Apply mask to both RGB and Alpha
    outColor = float4(Color.rgb * mask, Color.a * mask);
}",
