    {"name": "Size", "type": "float", "default_value": {"x": 0.5, "y": 0, "z": 0, "w": 0}},
    {"name": "Color", "type": "color", "default_value": {"x": 1.0, "y": 0.0, "z": 0.0, "w": 1.0}}
  ]
}

