  "file_name": "PentagonShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Helper: Perpendicular vector (right-hand)
float2 nm_perpRight(float2 e)
{
    return float2(e.y, -e.x);
}

// Helper: Distance from point p to segment ab
float nm_distPointToSegment(float2 p, float2 a, float2 b)
{
    float2 e = b - a;
    float ee = max(dot(e, e), 1e-12);
    float t = clamp(dot(p - a, e) / ee, 0.0, 1.0);
    float2 q = a + t * e;
    return length(p - q);
}

// Helper: Signed distance to a regular pentagon
// r = circumradius
float nm_sdPentagon(float2 p, float r)
{
    // 5 vertices for a regular pentagon
    float2 v[5];
    [unroll]
    for (int i = 0; i < 5; ++i)
    {
        // Start at 90 degrees (top) to be upright
        float ang = 0.5 * PI + (2.0 * PI * i) / 5.0;
        v[i] = r * float2(cos(ang), sin(ang));
    }

    float maxHalf = -1e9; // Max signed distance to edge lines (positive = outside)
    float minEdge = 1e9;  // Min distance to edge segments

    [unroll]
    for (int i = 0; i < 5; ++i)
    {
        int j = (i + 1) % 5;
        float2 a = v[i];
        float2 b = v[j];
        float2 e = b - a;
        float2 n = normalize(nm_perpRight(e)); // Outward normal

        maxHalf = max(maxHalf, dot(p - a, n));
        minEdge = min(minEdge, nm_distPointToSegment(p, a, b));
    }

    // If maxHalf <= 0, we are inside all half-spaces
    float sgn = (maxHalf <= 0.0) ? -1.0 : 1.0;
    return minEdge * sgn;
}

// Helper: Composite source over destination (straight alpha)
float4 nm_over(float4 src, float4 dst)
{
    float a = src.a + dst.a * (1.0 - src.a);
    float3 c = (src.rgb * src.a + dst.rgb * dst.a * (1.0 - src.a)) / max(a, 1e-8);
    return float4(c, a);
}

void PentagonShape_float(float2 UV, float Radius, float2 Center, float Rotation, float4 FillColor, float4 StrokeColor, float StrokeWidth, out float4 outColor)
{
    // PLAN:
    // 1) Recenter UV coordinates based on Center input.
    // 2) Rotate the coordinate system by -Rotation so the shape appears rotated by +Rotation.
    // 3) Calculate Signed Distance Field (SDF) for a regular pentagon.
    // 4) Compute Anti-Aliasing (AA) width using fwidth.
    // 5) Generate masks for Fill and Stroke.
    // 6) Composite Stroke over Fill for final result.

    // 1) Recenter
    float2 p = UV - Center;

    // 2) Rotate
    float c = cos(Rotation);
    float s = sin(Rotation);
    float2 pr = float2(c * p.x + s * p.y, -s * p.x + c * p.y);

    // 3) SDF
    // Ensure radius is non-negative. Input is circumradius.
    float d = nm_sdPentagon(pr, max(Radius, 0.0));

    // 4) AA
    float aa = fwidth(d);

    // 5) Masks
    // Fill: inside the shape (d < 0)
    float fillMask = 1.0 - smoothstep(0.0, aa, d);
    float4 fillOut = float4(FillColor.rgb, saturate(FillColor.a) * fillMask);

    // Stroke: band around the edge (abs(d) < width/2)
    float halfW = 0.5 * max(StrokeWidth, 0.0);
    float edgeDist = abs(d) - halfW;
    float strokeMask = 1.0 - smoothstep(0.0, aa, edgeDist);
    float4 strokeOut = float4(StrokeColor.rgb, saturate(StrokeColor.a) * strokeMask);

    // 6) Composite
    outColor = nm_over(strokeOut, fillOut);
}",
