{
  "file_name": "HexagonShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// SDF for a regular hexagon (flat-topped by default, rotates with UVs)
float sdHexagon(float2 p, float s)
{
    const float3 k = float3(-0.866025404, 0.5, 0.577350269);
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= float2(clamp(p.x, -k.z * s, k.z * s), s);
    return length(p) * sign(p.y);
}

void HexagonShape_float(float2 UV, float Size, float Rotation, float4 Color, out float4 outColor)
{
    // PLAN:
    // 1) Center the UV coordinates (0.5, 0.5 becomes 0,0).
    // 2) Rotate the coordinates to rotate the shape.
    // 3) Calculate the Signed Distance Field (SDF) for the hexagon.
    // 4) Apply smoothstep for crisp anti-aliased edges.
    // 5) Output the final color with alpha transparency.

    // 1. Center UV
    float2 p = UV - 0.5;

    // 2. Rotate (CCW rotation of shape requires CW rotation of coordinate system)
    float c = cos(Rotation);
    float s = sin(Rotation);
    p = float2(p.x * c + p.y * s, -p.x * s + p.y * c);

    // 3. Calculate SDF
    // Size represents the distance from center to edge (apothem) or vertex depending on def.
    // Here 'Size' roughly correlates to the radius.
    float dist = sdHexagon(p, Size);

    // 4. Anti-aliasing
    // fwidth gives a sharp 1-pixel edge regardless of scale, ensuring crispness
    // We use a small epsilon fallback to prevent division by zero or super hard edges
    float delta = fwidth(dist);
    float smoothing = max(delta, 0.0001);
    float edge = smoothstep(smoothing, -smoothing, dist);

    // 5. Output
    // Apply the mask to the color's alpha
    outColor = float4(Color.rgb * edge, Color.a * edge);
}",
