{
  "file_name": "HollowCircle",
  "hlsl_code": "void HollowCircle_float(float2 UV, float InnerRadius, float OuterRadius, float4 Color, out float4 outColor) {
    // PLAN:
    // 1) Center the UV coordinates at (0.5, 0.5).
    // 2) Calculate the distance from the center.
    // 3) Compute the SDF for the ring (hollow circle) using boolean subtraction (intersection of Outer and hole).
    // 4) Apply anti-aliasing using fwidth and smoothstep.
    // 5) Apply the calculated mask to the output color.

    // 1) Center UV coordinates
    float2 centered = UV - 0.5;

    // 2) Calculate distance from center
    float dist = length(centered);

    // 3) SDF Calculation
    // A ring is defined as being inside the OuterRadius AND outside the InnerRadius.
    // SDF Convention: Negative values are INSIDE the shape, Positive values are OUTSIDE.
    // - Inside Outer Circle: (dist - OuterRadius) < 0
    // - Outside Inner Circle: (InnerRadius - dist) < 0
    // Intersection operation is max(A, B)
    float sdf = max(dist - OuterRadius, InnerRadius - dist);

    // 4) Anti-aliasing
    // fwidth calculates the derivative of the distance, giving the width of a pixel in SDF space
    float aa = fwidth(dist);
    // Ensure we don't divide by zero (safety epsilon)
    aa = max(aa, 1e-5);

    // Create smooth mask: 1.0 inside, 0.0 outside, smooth gradient at edge
    float mask = 1.0 - smoothstep(0.0, aa, sdf);

    // 5) Output Color
    // Combine RGB with the mask applied to the Alpha channel
    outColor = float4(Color.rgb, Color.a * mask);
}",
