{
  "file_name": "FourPointStar",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Helper: Signed distance to a 4-pointed star (symmetric)
// p: centered coordinates (folded to 1st quadrant)
// r: outer radius (tip distance)
// rInner: inner radius (valley distance)
// Returns negative inside, positive outside
float sdStar4_Helper(float2 p, float r, float rInner) {
    // Fold to first quadrant to simplify symmetry (axis aligned fold)
    p = abs(p);
    // Fold along diagonal (y=x) to reduce to 1/8th sector (0 to 45 degrees)
    if (p.y > p.x) p.xy = p.yx;

    // We are now in the sector bounded by the X-axis and the line y=x.
    // The star boundary in this sector is a single line segment connecting:
    // 1. The tip on the X-axis: (r, 0)
    // 2. The inner "valley" vertex: (rInner * cos(45), rInner * sin(45))

    float k = 0.70710678; // 1/sqrt(2)
    float2 tip = float2(r, 0.0);
    float2 valley = float2(rInner * k, rInner * k);

    // Calculate distance to the segment [tip, valley]
    float2 e = valley - tip; // Vector along the edge
    float2 w = p - tip;      // Vector from tip to point

    // Project point onto the infinite line of the edge, clamped to segment
    // h=0 is the tip, h=1 is the valley
    float h = clamp(dot(w, e) / dot(e, e), 0.0, 1.0);
    float2 dVec = w - e * h; // Vector from closest point on segment to p

    float d = length(dVec);

    // Determine sign (Inside vs Outside)
    // We use the 2D cross product (z-component) to check winding/side
    // Vector 'e' points inwards (from tip to valley).
    // If we are "left" of 'e' (positive cross product), we are inside the star (towards the origin).
    float cp = e.x * w.y - e.y * w.x;

    // SDF Convention: Negative is inside
    return (cp > 0.0) ? -d : d;
}

void FourPointStar_float(float2 UV, float Size, float Sharpness, float4 Color, out float4 outColor) {
    // PLAN:
    // 1) Center the UV coordinates to (0,0) range.
    // 2) Determine inner radius based on Size and Sharpness inputs.
